            aOrbiterA = (aWandererD + RotL64(aScatter, 5U)) + 0x6E6AAFCAC79975C6ULL;
            aOrbiterG = (((aWandererH + RotL64(aPrevious, 27U)) + RotL64(aCarry, 41U)) + 0x2559C92F819E63E1ULL) + aTwistOrbiterAssignSaltB[((aIndex + 23U)) & S_SALT1];
            aOrbiterJ = ((aWandererF + RotL64(aIngress, 13U)) + 0xEB299108BB8F9A9DULL) + aTwistOrbiterAssignSaltA[((aIndex + 14U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aCross, 20U)) + RotL64(aCarry, 29U)) + 0x85D17181EB4F29A0ULL;
            aOrbiterK = (aWandererC + RotL64(aPrevious, 57U)) + 0xD45261E8F3F17ADBULL;
            aOrbiterH = ((aWandererJ + RotL64(aIngress, 51U)) + RotL64(aCarry, 5U)) + 0x2B12E06F4EDBEAFEULL;
            aOrbiterB = (aWandererG + RotL64(aScatter, 35U)) + 0x7D2D3F8E1987AA69ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterG) + 0xB1A6FED32BD4D0D2ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0xD6EC1EDE044ADF8EULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xC398EA3E819FAC4DULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0xEB8720D437352064ULL;
