            //
            aOrbiterK = ((aOrbiterK + aOrbiterH) + 0x6F3D3927D873D5BDULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x9B546D95D7451ED1ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x64276D2CE378CBBBULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x06C79C84D853497CULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x8AB082C85DAC0778ULL;
