            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x3AA13C5B4F79E275ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x918EB1CD98B4B368ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 21U)) & S_SALT1];
