            aCross = (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 12843U)) & S_BLOCK1], 13U) ^ RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 13086U)) & S_BLOCK1], 48U));
