            //
            aOrbiterC = (aWandererI + RotL64(aIngress, 47U)) + 0x180893C2BEF5DC63ULL;
            aOrbiterK = (((aWandererG + RotL64(aCross, 35U)) + RotL64(aCarry, 53U)) + 0x0F738451DECC250BULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterB = (aWandererA + RotL64(aPrevious, 41U)) + 0x5E9B6E3D7A45891BULL;
            aOrbiterD = ((aWandererB + RotL64(aScatter, 57U)) + RotL64(aCarry, 41U)) + 0xC1654909F5D4B1B6ULL;
