            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0x19773A0D638B6B8AULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterK) ^ 0x4A55CE8D189D9783ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1];
