            aOrbiterJ = (((aWandererE + RotL64(aCross, 23U)) + RotL64(aCarry, 57U)) + 0x58F9A1BE5875EA53ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
