            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0x3C1175F410381C5EULL) + aTwistOrbiterUpdateSaltC[((aIndex + 26U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0xA8F55C3702C78E68ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 9U)) & S_SALT1];
