            aOrbiterK = (((aWandererJ + RotL64(aIngress, 11U)) + RotL64(aCarry, 5U)) + 0x731559BC47653A3EULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterD = (((aWandererA + RotL64(aCross, 51U)) + RotL64(aCarry, 53U)) + 0x9868F948C1FC4AA6ULL) + aTwistOrbiterAssignSaltD[((aIndex + 26U)) & S_SALT1];
