            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0x72E0B48D76A3D4ADULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0x35CE564A88D2F918ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1];
