            aOrbiterA = (((aWandererE + RotL64(aPrevious, 23U)) + RotL64(aCarry, 57U)) + 0x38725D69C37E5CE7ULL) + aTwistOrbiterAssignSaltB[((aIndex + 9U)) & S_SALT1];
