            aIngress = (RotL64(aPoisonLaneA[((aIndex + 7919U)) & S_BLOCK1], 27U) ^ RotL64(aPoisonLaneB[((aIndex + 5342U)) & S_BLOCK1], 54U));
            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 5536U)) & W_KEY1], 13U) ^ RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 7816U)) & S_BLOCK1], 35U));
