            aCross = (RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 8150U)) & S_BLOCK1], 35U) ^ RotL64(aLightningLaneC[((S_BLOCK1 - aIndex + 5309U)) & S_BLOCK1], 27U));
            aCross ^= (RotL64(aWoodLaneA[((S_BLOCK1 - aIndex + 5374U)) & S_BLOCK1], 43U) ^ RotL64(aMagmaLaneD[((aIndex + 57U)) & S_BLOCK1], 4U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aIngress, 5U) ^ RotL64(aCross, 24U)) + (RotL64(aCarry, 41U) + RotL64(aPrevious, 53U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterH = ((aWandererD + RotL64(aIngress, 5U)) + RotL64(aCarry, 23U)) + 0x62E7436DF2505D10ULL;
            aOrbiterJ = ((aWandererB + RotL64(aPrevious, 41U)) + RotL64(aCarry, 51U)) + 0x82358AE86F64D447ULL;
            aOrbiterB = ((aWandererH + RotL64(aScatter, 47U)) + 0x6D604EDDE884EA91ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 23U)) & S_SALT1];
            aOrbiterK = ((aWandererI + RotL64(aCross, 23U)) + 0x1725BD010419CB24ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterG = (aWandererC + RotL64(aIngress, 60U)) + 0x73E4B4D951194615ULL;
            aOrbiterF = (aWandererK + RotL64(aScatter, 35U)) + 0x22C8B87E4079CAF4ULL;
            aOrbiterE = ((aWandererG + RotL64(aCross, 29U)) + RotL64(aCarry, 35U)) + 0x9F32926994626896ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xBB6FC50AB327AC1DULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0xB1D6522DCA33AF64ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC7A77722434DE36BULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xD74A176AB9150AA4ULL;
