            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x5F37D551B6F11A2BULL;
            aOrbiterF = RotL64((aOrbiterF * 0x70143DA907324F57ULL), 11U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x043013691EAACB76ULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0x2D7B01B46BD678F2ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 8U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x29A966511A45D04FULL), 3U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0xBB04BE9CD6E549B0ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x4AA3B297CD38B761ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x737823F3767D2309ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xACC15C552DB68642ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0xD46C12387E367B79ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xECA6F65FD1DA7B8DULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0xAE7BD2C189B5D86EULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xA2A2886850831D48ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x4DF70B2C26BCFBB3ULL), 35U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterE, 5U);
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterB, 47U));
            aIngress = aIngress + (RotL64(aOrbiterF, 53U) ^ aOrbiterH);
            aIngress = aIngress + RotL64(aOrbiterG, 27U);
