            //
            aWandererH = aWandererH + ((((RotL64(aScatter, 23U) + aOrbiterH) + RotL64(aOrbiterB, 43U)) + RotL64(aCarry, 23U)) + aKeyRotateWandererUpdateSaltD[((aIndex + 4U)) & S_SALT1]);
