            aWandererI = aWandererI ^ (((RotL64(aCross, 60U) + RotL64(aOrbiterG, 36U)) + aOrbiterK) + aKeyRotateWandererUpdateSaltB[((aIndex + 5U)) & S_SALT1]);
            aWandererC = aWandererC + ((RotL64(aScatter, 53U) + RotL64(aOrbiterG, 11U)) + aOrbiterJ);
