            aIngress = (RotL64(aShadowLaneB[((aIndex + 24246U)) & S_BLOCK1], 60U) ^ RotL64(aPoisonLaneD[((aIndex + 16510U)) & S_BLOCK1], 39U));
            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 20138U)) & W_KEY1], 13U) ^ RotL64(aIceLaneC[((aIndex + 18681U)) & S_BLOCK1], 23U));
