            //
            aCross = (RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 18547U)) & S_BLOCK1], 14U) ^ RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 17912U)) & S_BLOCK1], 53U));
            aCross ^= (RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 23701U)) & S_BLOCK1], 43U) ^ RotL64(aEarthLaneD[((aIndex + 18818U)) & S_BLOCK1], 23U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aPrevious, 3U) + RotL64(aCarry, 18U)) ^ (RotL64(aCross, 53U) ^ RotL64(aIngress, 35U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterB = (((aWandererJ + RotL64(aScatter, 37U)) + RotL64(aCarry, 53U)) + 0xC07A72763E38DF8DULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterC = (aWandererD + RotL64(aPrevious, 53U)) + 0xE07A572FB126315CULL;
            aOrbiterA = ((aWandererA + RotL64(aCross, 60U)) + RotL64(aCarry, 41U)) + 0x91AF057B08880D81ULL;
            aOrbiterI = ((aWandererC + RotL64(aIngress, 3U)) + RotL64(aCarry, 5U)) + 0x661D5055E9B8F996ULL;
            aOrbiterH = (aWandererF + RotL64(aCross, 29U)) + 0x98F774097F4CEB47ULL;
            aOrbiterK = ((aWandererK + RotL64(aScatter, 47U)) + 0x970EA8E475BD6D10ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterD = (aWandererE + RotL64(aPrevious, 23U)) + 0xC73EAEE480FDD872ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x5D633C52AA844F19ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x37E1EED21202A79BULL;
            aOrbiterA = RotL64((aOrbiterA * 0x04DB6591F629104FULL), 11U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0x232158DD6FC275EBULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
