            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xEE8793639A57B6A5ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x89210F8D51BB5BC5ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xD2D3F0FEAD2B941BULL), 39U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x44F244E10EBCF103ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0xBDCEF484DD29075BULL;
            aOrbiterH = RotL64((aOrbiterH * 0x491E9655E9FA7DABULL), 27U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0xD3EDE0694E1C5C5DULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0xFD7B2F52F9B994B2ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x851E6AB71DC054F3ULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x9BC29DF13CC4307CULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0x48D5FA4458347F22ULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 26U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x061A73436E39CC9BULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0xE9398993B3A7EF15ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0xF8A96C6B933B4760ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xBEC5554F316242F9ULL), 21U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterD, 23U);
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterH, 3U));
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterA, 35U));
            aIngress = aIngress + RotL64(aOrbiterC, 57U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA + ((((RotL64(aScatter, 5U) + aOrbiterD) + RotL64(aOrbiterB, 51U)) + RotL64(aCarry, 51U)) + aKeyRotateWandererUpdateSaltA[((aIndex + 14U)) & S_SALT1]);
