            aWandererD = aWandererD + (((RotL64(aIngress, 47U) + aOrbiterA) + RotL64(aOrbiterD, 29U)) + RotL64(aCarry, 37U));
            aWandererC = aWandererC ^ ((RotL64(aScatter, 23U) + aOrbiterD) + RotL64(aOrbiterI, 43U));
            aWandererJ = aWandererJ + (((RotL64(aCross, 53U) + aOrbiterH) + RotL64(aOrbiterK, 23U)) + aKeyRotateWandererUpdateSaltC[((aIndex + 15U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererK, 52U) ^ aWandererD);
