            aPrevious = aIngress;
            //
            aIngress = (RotL64(aShadowLaneC[((aIndex + 25653U)) & S_BLOCK1], 51U) ^ RotL64(aShadowLaneA[((aIndex + 26526U)) & S_BLOCK1], 35U));
