            //
            aOrbiterA = (aWandererK + RotL64(aScatter, 29U)) + 0x086ED293BBA0E6EFULL;
            aOrbiterC = ((aWandererE + RotL64(aCross, 44U)) + RotL64(aCarry, 53U)) + 0x20F8AADC070A5F4DULL;
            aOrbiterE = (((aWandererA + RotL64(aPrevious, 3U)) + RotL64(aCarry, 37U)) + 0x292E1A81FD7D7CF9ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterF = (aWandererI + RotL64(aIngress, 51U)) + 0xEFEC3BAF79962A45ULL;
            aOrbiterD = ((aWandererD + RotL64(aScatter, 57U)) + RotL64(aCarry, 5U)) + 0xB70955B7762CA197ULL;
            aOrbiterB = (aWandererJ + RotL64(aCross, 35U)) + 0x814FC65898AE1D3CULL;
            aOrbiterJ = ((aWandererG + RotL64(aPrevious, 21U)) + 0x7DB16C47755BB193ULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 6U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x9E990C2ACC05E2D5ULL;
