            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x358D24E720FB3BB9ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0xD25165C076519B76ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x5C872DE7756C9C7DULL), 3U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0x768B9ED2A9DD1922ULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0x52C3DB6BA287B415ULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xB8750A336532F37DULL), 27U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x53B0523AEB2E1C85ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0xA107A8BB5DE36CE1ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xA7978B4435FB7F71ULL), 57U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0xBA8F930C20D78F09ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0x497EC9153A8D4EC2ULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 4U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x6CEA5A3CB0AFB557ULL), 47U);
