            aWandererE = aWandererE + (((RotL64(aIngress, 21U) + RotL64(aOrbiterC, 43U)) + aOrbiterH) + aKeyRotateWandererUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aScatter, 38U) + RotL64(aOrbiterK, 27U)) + aOrbiterI);
