            aWandererH = aWandererH ^ ((RotL64(aCross, 27U) + RotL64(aOrbiterF, 52U)) + aOrbiterK);
            aWandererF = aWandererF + ((RotL64(aPrevious, 11U) + RotL64(aOrbiterA, 13U)) + aOrbiterJ);
            aWandererG = aWandererG ^ ((RotL64(aScatter, 29U) + RotL64(aOrbiterB, 37U)) + aOrbiterE);
            aWandererK = aWandererK + (((RotL64(aCross, 42U) + aOrbiterA) + RotL64(aOrbiterC, 19U)) + RotL64(aCarry, 53U));
            //
            aCarry = aCarry + (RotL64(aWandererF, 46U) ^ aWandererI);
