            //
            aOrbiterB = (aWandererG + RotL64(aScatter, 13U)) + 0x9565B5CA46BDBB62ULL;
            aOrbiterH = ((aWandererA + RotL64(aIngress, 37U)) + 0xF15CDD6DB87E583BULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 13U)) & S_SALT1];
            aOrbiterG = (aWandererF + RotL64(aCross, 41U)) + 0x2349249B6B424A32ULL;
