            aOrbiterD = (aWandererI + RotL64(aCross, 44U)) + 0xC14E9EC3377B7E0EULL;
            aOrbiterF = (aWandererE + RotL64(aScatter, 35U)) + 0xEB2165F94C725D81ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aPrevious, 53U)) + 0x9569B2C0C5E30B64ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 21U)) & S_SALT1];
