            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0xDAE6A43C32943CFEULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 4U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0x9B48B13E63A12BEAULL;
            aOrbiterG = RotL64((aOrbiterG * 0x03B3C76A8644AE5BULL), 27U);
