            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x2DC6093230EA2C99ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x795AE5D8CEAA4097ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x510FBAF485EEDAD3ULL), 3U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterJ) + 0x697242B256C273BEULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 8U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x40AB712D35ECC05EULL;
            aOrbiterH = RotL64((aOrbiterH * 0x2051ABCFB82D10C1ULL), 35U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x824B90F5E9391070ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x75E5056C46984A24ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x8663F2F6BBCC91F9ULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x82C1CE6CF8C7EADDULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x1F27CCF96B054508ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xB958789144EE10C7ULL), 53U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x09ED0F64875E86A8ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x7A0C5F19638C3F40ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x389F33A195B8EDBDULL), 57U);
