            aOrbiterF = RotL64((aOrbiterF * 0xF70D642DA7975549ULL), 39U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xD46BB604B782CBEDULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x9108378A70607011ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x960C981D274DAD6DULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xC5E68B1B5C16021FULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0x03B692D0C4389183ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xB11F990BD1D7D653ULL), 21U);
