            aCross = (RotL64(aVaporLaneC[((S_BLOCK1 - aIndex + 486U)) & S_BLOCK1], 51U) ^ RotL64(aMagmaLaneB[((S_BLOCK1 - aIndex + 1780U)) & S_BLOCK1], 23U));
            aCross ^= (RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 605U)) & S_BLOCK1], 41U) ^ RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 6114U)) & S_BLOCK1], 4U));
            aCross = TwistMix64::DiffuseA(aCross);
