            //
            aOrbiterC = ((aWandererB + RotL64(aCross, 5U)) + 0xA5A4CCD73F14A594ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterI = ((aWandererG + RotL64(aIngress, 29U)) + RotL64(aCarry, 27U)) + 0x4DF1C11245B6845FULL;
            aOrbiterB = ((aWandererK + RotL64(aScatter, 43U)) + RotL64(aCarry, 43U)) + 0xDC889EA7658D0497ULL;
            aOrbiterH = (aWandererE + RotL64(aPrevious, 58U)) + 0x1B8D4244E61D8BD6ULL;
            aOrbiterJ = (((aWandererC + RotL64(aCross, 37U)) + RotL64(aCarry, 13U)) + 0xEB6E66359DCAD60FULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterE = (aWandererF + RotL64(aIngress, 13U)) + 0xD1DAB4A24F32EDA9ULL;
