            aOrbiterB = ((aOrbiterB ^ aOrbiterC) ^ 0xB75AD04F270BC775ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 17U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x2A84D56D4F9AB19BULL), 47U);
