            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0xA409CD407EE29A77ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 23U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x6B52D4B433DBB4B0ULL;
