            aIngress ^= (RotL64(aWindLaneC[((aIndex + 6362U)) & S_BLOCK1], 19U) ^ RotL64(aWindLaneB[((aIndex + 8226U)) & S_BLOCK1], 29U));
            aIngress = TwistMix64::DiffuseC(aIngress);
