            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 6816U)) & S_BLOCK1], 53U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 8889U)) & S_BLOCK1], 36U));
            aCross ^= (RotL64(aVaporLaneA[((S_BLOCK1 - aIndex + 6576U)) & S_BLOCK1], 3U) ^ RotL64(aWoodLaneC[((aIndex + 6207U)) & S_BLOCK1], 27U));
