            aOrbiterI = RotL64((aOrbiterI * 0x3EF18CDEEACE796DULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0xD8E6E4996EA7E7E2ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0xABC6576152DBCB69ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x8634F2E35B790175ULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x14B9C757D4712F2BULL;
